def solve_l3(dots, cur, shapes):
    # shapes: name -> (dr_min..) function
    placements={}
    for name,(r0,c0) in cur.items():
        f=shapes[name]; pl=[]
        for R in range(64):
            if (R-r0)%3: continue
            for C in range(64):
                if (C-c0)%3: continue
                s=f(R,C)
                cov=frozenset(i for i,d in enumerate(dots) if d in s)
                if cov: pl.append(((R,C),cov))
        placements[name]=pl
    names=list(cur)
    sols=[]
    def rec(i,used,chosen,covered):
        if len(covered)==len(dots):
            sols.append((dict(chosen), covered)); return
        if i==len(names): return
        nm=names[i]
        # option: skip this object (place it somewhere covering nothing)
        rec(i+1,used,chosen,covered)
        for pos,cov in placements[nm]:
            if used & cov: continue
            chosen[nm]=pos
            rec(i+1, used|cov, chosen, covered|cov)
            del chosen[nm]
    rec(0,frozenset(),{},frozenset())
    return placements, sols

