def canonD(s,w=5,hh=5):
    bm=[[int(s[r*w+c]) for c in range(w)] for r in range(hh)]
    best=None; cur=bm
    for k in range(4):
        best=min(best,h(cur)) if best else h(cur)
        mir = [row[::-1] for row in cur]
        best=min(best,h(mir))
        cur=rot(cur)
    return best
