        dd=(b-a)%7
        presses = ['DOWN']*dd if dd<=3 else ['UP']*(7-dd)
        if presses: need.append((i,presses))
    def dist(a,b): return min((b-a)%n,(a-b)%n)
    best=None
    for perm in itertools.permutations(range(len(need))):
        cur=c; tot=0
        for k in perm:
            i=need[k][0]; tot+=dist(cur,i); cur=i
        if best is None or tot<best[0]: best=(tot,perm)
