def lvl3_read(frame):
    def words(r0,c0,c1):
        out=[]; c=c0
        while c+4<=c1:
            out.append(canon(h(bits(frame,r0,r0+4,c,c+4)))); c+=7
        return out
    rules=[]
    for (yr,yc0,yc1),(br,bc0,bc1) in [((5,6,10),(5,16,20)),((5,29,40),(5,46,57)),((14,6,10),(14,16,28)),((14,36,47),(14,53,57)),((23,6,24),(23,30,34)),((23,43,47),(23,53,57))]:
