    cur=None
    for n in frame.segmentation['nodes']:
        if n['color']=='W': cur=(min(p[1] for p in n['boundary'])-8)//7
    return rules, yb, bb, cur

def decode(rules, yb):
    n=len(yb); res=[]
    def dfs(i, acc, bl):
        if i==n:
            if len(bl)==7: res.append(list(acc))
            return
        for j,(yw,bw) in enumerate(rules):
            L=len(yw)
            if i+L<=n and yb[i:i+L]==yw:
                acc.append(j); dfs(i+L, acc, bl+bw); acc.pop()
    dfs(0,[],[])
    return res

