            assert SP.get(S,S)==S and SP.setdefault(S,P)==P, ('ambig S',S)
        elif {ca,cb}=={'P','Y'}:
            P = ga if ca=='P' else gb; Y = gb if cb=='Y' else ga
            assert PY.get(P,P)==P and PY.setdefault(P,Y)==Y, ('ambig P',P)
    target=[PY[SP[s]] for s in sb]
    li={v:i for i,v in enumerate(CY)}
