        if pr: need.append((i,pr))
    import itertools
    def dist(x,y): return min((y-x)%n,(x-y)%n)
    best=None
    for perm in itertools.permutations(range(len(need))):
        cc=cur; tot=0
        for k in perm:
            i=need[k][0]; tot+=dist(cc,i); cc=i
        if best is None or tot<best[0]: best=(tot,perm)
    tot,perm=best
    plan=[]; cc=cur
    for k in perm:
        i,pr=need[k]
        d=(i-cc)%n
        plan += (['RIGHT']*d if d<=dist(cc,i) else ['LEFT']*(n-d))
        cc=i; plan+=pr
    return CY,li,target,yb,cur,plan,[need[k][0] for k in perm]

