def blockgrid(frame):
    seg = frame.segmentation
    black=set(); blue={}
    for n in seg['nodes']:
        cells=set()
        for (r,c0,c1) in n['runs']:
            for c in range(c0,c1+1): cells.add((r,c))
        if n['color']=='B':
            if n['pixels']>200: black=cells
        elif n['color']=='S':
            blue[n['id']]=cells
    grid=[]
    for br in range(10):
        row=''
        for bc in range(9):
            r0=9+5*br; c0=9+5*bc
            nb=sum(1 for r in range(r0,r0+5) for c in range(c0,c0+5) if (r,c) in black)
            ns=0
