            row += 'B' if nb==25 else ('S' if ns==25 else ('.' if nb==0 and ns==0 else '?'))
        grid.append(row)
    return grid, {k:(min(r for r,c in v)//5-1, min(c for r,c in v)//5-1) for k,v in blue.items()}

